test('read-only actual order tax target prints first-money precision and keeps full order totals after receipts',async()=>{const f=fixture(false);try{f.w.eval(fs.readFileSync('dist/self-core.js','utf8'));f.w.AuthUI.settings=()=>({commonDefaults:{amountDigits:2,trailingZeros:true},conveniences:{pageSize:50,numberDecimals:0}});let db=JSON.parse(f.stored());db=C.command(db,'convert',{id:f.ids.purchaseorder,type:'purchase',date:C.today(),quantities:{L1:1}}).db;f.w.localStorage.setItem('ecount-inventory-v2',JSON.stringify(db));const before=f.stored(),host=f.render('purchaseorder','report');host.querySelector('[aria-label="메뉴 집계"]').click();for(const [i,axis]of ['품목별','거래처별'].entries()){const c=host.querySelector('[aria-label="집계조건'+(i+1)+'"]');c.value=axis;c.dispatchEvent(new f.w.Event('change',{bubbles:true}));}f.click('집계대상 선택',host);const dlg=f.d.getElementById('purchasing-summary-targets');dlg.querySelector('[aria-label="집계대상 부가세"]').click();f.click('적용(F8)',dlg);f.click('검색(F8)',host);assert.deepEqual([...host.querySelectorAll('thead th')].map(x=>x.textContent),['품목명[규격]','거래처','부가세']);assert.ok([...host.querySelectorAll('tbody tr')].every(x=>x.lastElementChild.textContent==='20.00'));f.click('Search(F3)',host);host.querySelector('[aria-label="집계대상 지우기"]').click();host.querySelector('[aria-label="조회 시작일"]').value='2027-01-01';f.click('검색(F8)',host);f.click('Excel(화면)',host);const csv=await blobText(f.w,f.blobs[0]);assert.ok(csv.split('\r\n').filter(Boolean).every(line=>line.split(',').length===3));f.click('인쇄',host);const print=f.d.getElementById('inventory-dialog');assert.equal(print.querySelector('[data-row-kind="subtotal"] th').colSpan,2);assert.match(print.textContent,/집계대상 부가세/);assert.ok([...print.querySelectorAll('tbody tr')].every(x=>x.lastElementChild.textContent==='20.00'));f.click('×',print);host.querySelector('[aria-label="조회 시작일"]').value=C.today().slice(0,7)+'-01';f.click('검색(F8)',host);assert.equal(host.querySelectorAll('thead th').length,6);assert.equal(host.querySelector('[data-row-kind="data"]').children[2].textContent,'2');assert.equal(f.stored(),before);assert.deepEqual(f.errors,[]);}finally{f.w.close();}});

test('purchasing list currency filters keep legacy KRW vouchers and request numbers search only document IDs',()=>{
 const f=fixture();try{
  let db=JSON.parse(f.stored());const foreign={};
  for(const type of ['request','purchaseorder','purchase']){const saved=C.command(db,'document',{type,date:C.today(),warehouse:'W001',partner:'V001',currency:'USD',status:'진행',lines:[{item:'M001',qty:2,price:2}]});db=saved.db;foreign[type]=saved.result.id;delete db.documents.find(d=>d.id===f.ids[type]).currency;db.documents.find(d=>d.id===foreign[type]).memo=f.ids[type];}
  f.w.InventoryUI.replace(db);const before=f.stored();
  for(const type of ['request','purchaseorder','purchase']){const host=f.render(type,'list'),currency=host.querySelector('[aria-label="내.외자구분"]');assert.ok(currency);currency.value='외자';f.click('검색(F8)',host);assert.equal(host.querySelectorAll('tbody .inv-link').length,1);assert.ok(host.querySelector('tbody .inv-link').textContent.includes(foreign[type]));currency.value='내자';f.click('검색(F8)',host);assert.equal(host.querySelectorAll('tbody .inv-link').length,1);assert.ok(host.querySelector('tbody .inv-link').textContent.includes(f.ids[type]));currency.value='전체';
   const number=host.querySelector('[aria-label="발주요청No."]');if(type==='request'){assert.ok(number);number.value='  '+f.ids[type].toLowerCase()+'  ';f.click('검색(F8)',host);assert.equal(host.querySelectorAll('tbody .inv-link').length,1);assert.ok(host.querySelector('tbody .inv-link').textContent.includes(f.ids[type]));number.value='%';f.click('검색(F8)',host);assert.equal(host.querySelectorAll('tbody .inv-link').length,0);}else assert.equal(number,null);
   assert.equal(f.stored(),before);
  }assert.deepEqual(f.errors,[]);
 }finally{f.w.close();}
});
