test('plan search shortcut ownership blocks modal, modifier, repeat and IME events through InventoryUI',()=>{
 const f=fixture();try{const host=f.render('plan','list'),quick=host.querySelector('[aria-label="발주계획 빠른검색"]'),form=host.querySelector('[aria-label="발주계획 상세검색"]');const key=options=>quick.dispatchEvent(new f.w.KeyboardEvent('keydown',{key:'F3',bubbles:true,cancelable:true,...options}));for(const options of [{ctrlKey:true},{altKey:true},{metaKey:true},{shiftKey:true},{repeat:true},{isComposing:true}]){key(options);assert.equal(form.hidden,true);}key({});assert.equal(form.hidden,false);assert.equal(f.d.activeElement.getAttribute('aria-label'),'발주계획 시작일');key({});assert.equal(form.hidden,true);assert.equal(f.d.activeElement,quick);const before=f.stored();const dialog=f.d.createElement('dialog');dialog.open=true;const control=f.d.createElement('input');dialog.append(control);host.append(dialog);control.dispatchEvent(new f.w.KeyboardEvent('keydown',{key:'F3',bubbles:true,cancelable:true}));assert.equal(form.hidden,true);assert.equal(f.stored(),before);assert.deepEqual(f.errors,[]);}finally{f.w.close();}
});

