for(const type of ['request','purchaseorder','purchase'])test(type+' purchasing search criteria wait for explicit apply and preserve previous success on invalid dates',()=>{
 const f=fixture();try{
  let db=JSON.parse(f.stored());db.masters.projects=[{code:'STATE-A',name:'조건 A'},{code:'STATE-B',name:'조건 B'}];db.documents.find(d=>d.id===f.ids[type]).project='STATE-A';
  db=C.command(db,'document',{type,date:C.today(),warehouse:'W001',partner:'V001',project:'STATE-B',status:'진행',lines:[{item:'M001',qty:1,price:222}]}).db;
  const wanted=db.documents.at(-1).id;f.w.InventoryUI.replace(db);const before=f.stored(),host=f.render(type,'list'),ctl=label=>host.querySelector('[aria-label="'+label+'"]'),rows=()=>[...host.querySelectorAll('tbody .inv-link')].map(x=>x.textContent),change=(label,value)=>{ctl(label).value=value;ctl(label).dispatchEvent(new f.w.Event('change',{bubbles:true}));};
  f.click('Search(F3)',host);change('프로젝트 필터','STATE-B');assert.equal(rows().length,2,'draft criteria must not replace the current list');
  f.click('검색(F8)',host);assert.equal(rows().length,1);assert.match(rows()[0],new RegExp(wanted));assert.equal(host.querySelector('.inv-filters').hidden,true,'successful search closes its panel as observed in the original');
  ctl('전표 선택 '+wanted).click();f.click('Search(F3)',host);change('프로젝트 필터','STATE-A');ctl('자료 검색').value='pending-no-match';ctl('자료 검색').dispatchEvent(new f.w.Event('input',{bubbles:true}));
  ctl('전체 상태 조회').click();assert.equal(rows().length,1);assert.match(rows()[0],new RegExp(wanted));assert.equal(ctl('전표 선택 '+wanted).checked,true,'tab refresh must keep applied search and selection');
  change('시작일','2099-12-31');change('종료일','2000-01-01');f.click('검색(F8)',host);assert.equal(rows().length,1);assert.match(host.querySelector('[role="alert"]').textContent,/시작일/);assert.equal(host.querySelector('.inv-filters').hidden,false);assert.equal(ctl('전표 선택 '+wanted).checked,true);assert.equal(f.stored(),before);
 }finally{f.w.close();}
});
