for(const type of ['request','purchaseorder','purchase'])test(type+' multiple references and modified sort apply only on F8, preserve legacy search forms and never store search changes',async()=>{const f=fixture();try{let db=JSON.parse(f.stored());const base=db.documents.find(d=>d.id===f.ids[type]);db.masters.projects.push({code:'P2',name:'두번째 프로젝트'});for(const [suffix,partner,item,warehouse,project,time]of [['B','V001','P001','W001','P2','2028-01-02T00:00:00.000Z'],['C','V001','M001','W002','','2028-01-03T00:00:00.000Z'],['D','V001','M001','W001','','2028-01-01T00:00:00.000Z']]){const clone=C.clone(base);clone.id=base.id+'-'+suffix;clone.warehouse=warehouse;clone.project=project;clone.partner=partner;clone.lines=[{...clone.lines[0],item}];clone.modifiedAt=time;db.documents.push(clone);}base.modifiedAt='2027-01-01T00:00:00.000Z';const oldFields=[f.w.FormCore.field('partner','내 거래처','reference',{defaultValue:'V001'}),f.w.FormCore.field('warehouse','창고','reference'),f.w.FormCore.field('item','품목','reference'),f.w.FormCore.field('project','프로젝트','reference')];db=C.command(db,'formSave',{key:'doc:'+type,context:'search',form:{id:'old-search',name:'기존 검색',context:'search',fields:oldFields,page:{}}}).db;db=C.command(db,'formActivate',{key:'doc:'+type,context:'search',id:'old-search'}).db;f.w.InventoryUI.replace(db);f.w.AuthUI.can=p=>p==='inventory.read';const stored=f.stored(),host=f.render(type,'list'),control=id=>host.querySelector('select[data-form-field="'+id+'"]'),list=()=>[...host.querySelectorAll('tbody .inv-link')].map(b=>b.textContent.split(' / ')[1]);assert.equal(control('partner').getAttribute('aria-label'),'내 거래처');assert.equal(control('partner').value,'V001');const initial=list();control('warehouse').setReferenceValues(['W001','W002']);control('item').setReferenceValues(['M001','P001']);control('project').setReferenceValues(['P2']);if(type!=='purchaseorder')host.querySelector('[aria-label="수정일자순(정렬)"]').checked=true;else assert.equal(host.querySelector('[aria-label="수정일자순(정렬)"]'),null);control('project').dispatchEvent(new f.w.Event('change'));assert.deepEqual(list(),initial);f.click('검색(F8)',host);assert.deepEqual(list(),[base.id+'-B']);control('project').value='';f.click('검색(F8)',host);assert.deepEqual(list(),type==='purchaseorder'?[base.id,base.id+'-B',base.id+'-C',base.id+'-D']:[base.id+'-C',base.id+'-B',base.id+'-D',base.id]);const csvBefore=f.blobs.length;f.click('Excel (CSV)',host);assert.equal(f.blobs.length,csvBefore+1);const csv=await blobText(f.w,f.blobs.at(-1));if(type!=='purchaseorder')assert.ok(csv.indexOf(base.id+'-C')<csv.indexOf(base.id+'-B'));assert.equal(f.stored(),stored);assert.deepEqual(f.errors,[]);}finally{f.w.close();}});
test('multiple reference drafts and successful sort survive layout repaint independently from the displayed result',()=>{const f=fixture();try{const host=f.render('request','list');const item=host.querySelector('[data-form-field="item"] select')||host.querySelector('select[data-form-field="item"]');item.setReferenceValues(['M001','P001']);f.click('검색(F8)',host);item.setReferenceValues(['M003','M004']);const chooser=host.querySelector('.form-option-bar select[aria-label="적용 양식"]');chooser.value='default';chooser.dispatchEvent(new f.w.Event('change'));const next=host.querySelector('select[data-form-field="item"]');assert.deepEqual(Array.from(next.getReferenceValues()),['M003','M004']);assert.equal(host.querySelectorAll('tbody .inv-link').length,1);assert.equal(host.querySelector('[role="status"]').hidden,false);assert.deepEqual(f.errors,[]);}finally{f.w.close();}});
